def sigma1(n):
    res = 1
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            p_sum = 1
            p_pow = 1
            while temp % d == 0:
                p_pow *= d
                p_sum += p_pow
                temp //= d
            res *= p_sum
        d += 1
    if temp > 1:
        res *= (1 + temp)
    return res

