import math

def is_pretty(m, n, alpha, k):
    if m <= 0 or n <= 0:
        return False
    return m * math.ceil(n * alpha) - n * math.floor(m * alpha) == k

def find_cool(k, alpha, max_val):
    cool_pairs = []
    for m in range(1, max_val):
        for n in range(1, max_val):
            if is_pretty(m, n, alpha, k):
                if not is_pretty(m - n, n, alpha, k) and not is_pretty(m, n - m, alpha, k):
                    cool_pairs.append((m, n))
    return cool_pairs

alpha = math.sqrt(2)
print(f"k=3, cool_pairs={find_cool(3, alpha, 50)}")
print(f"k=1, cool_pairs={find_cool(1, alpha, 50)}")
print(f"k=2, cool_pairs={find_cool(2, alpha, 50)}")
